  "headline": "FDA's records trace our supply to a plant classified OAI 520 days before the shortage posting and again 253 days after",
  "headline_cites": ["D4", "D5"],
  "sentences": [
    {
      "text": "FDA posted the dacarbazine shortage on 2021-10-20 and as of 2026-10-21 it has been on the list for 60 months.",
      "cites": ["D12"]
    },
    {
      "text": "An inspection of Fresenius Kabi USA, LLC (FEI 1450022) ended 2020-05-18 and was classified OAI, with the classification letter dated 2024-05-22, 520 days before the shortage posting.",
      "cites": ["D4", "E12"]
    },
    {
      "text": "A second inspection of the same plant ended 2022-06-30 and was also classified OAI, with the classification letter dated 2024-04-30, 253 days after the shortage posting.",
      "cites": ["D5", "E13"]
    },
    {
      "text": "A later inspection ended 2023-08-24 and was classified VAI, 673 days after the shortage posting.",
      "cites": ["D6", "E14"]
    },
    {
      "text": "Corvale General holds two NDCs for dacarbazine: one from Hikma Pharmaceuticals USA Inc. (NDC 00143924510) and one from Fresenius Kabi USA, LLC (NDC 63323012710).",
      "cites": ["E3", "E4"]
    },
    {
      "text": "The Fresenius Kabi NDC is manufactured at the inspected plant (FEI 1450022) per the label.",
      "cites": ["E15"]
    },
    {
      "text": "The top-ranked option by rule is to transfer 3 units from Corvale General to Corvale East, which would give Corvale East 6 days on hand while Corvale General retains two weeks.",
      "cites": ["D9"]
    }
  ]
}
